UPDATE products SET size = $pd$500 ml$pd$, tagline = $pd$Polyherbal Ayurvedic concoction for liver and digestive wellness$pd$, content = $pd${"highlights":["11 Ayurvedic botanicals","Bhumyamalaki, Kalmegh & Kutki","No added colours or sugar","GMP certified, made in India"],"summary":"A botanical-based wellness product formulated with traditional herbal ingredients, designed to support normal liver function, digestive wellness and overall well-being.","description":["TranzLife Liver Booster (LiverDetox) is a polyherbal Ayurvedic concoction that brings together 11 traditional botanicals associated with liver and digestive wellness, led by Bhumyamalaki, Kalmegh and Kutki.","Each 10 ml contains Bhumyamalaki (Phyllanthus niruri) 500 mg, Kalmegh (Andrographis paniculata) 400 mg, Kutki (Picrorhiza kurroa) 400 mg, Punarnava (Boerhaavia diffusa) 300 mg, Bhringraj (Eclipta alba) 300 mg, Daruharidra (Berberis aristata) 200 mg, Guduchi (Tinospora cordifolia) 200 mg, Amla (Emblica officinalis) 200 mg, Haritaki (Terminalia chebula) 200 mg, Turmeric (Curcuma longa) 150 mg and black pepper (Piper nigrum) 50 mg, with excipients q.s."],"benefits":["Supports normal liver function","Provides antioxidant support","Supports natural metabolic processes","Supports digestive health and appetite","A blend of traditional botanical ingredients","Designed for everyday wellness support"],"ingredients":["bhumyamalaki","kalmegh","kutki","punarnava","bhringraj","daruharidra","giloy","amla","haritaki","turmeric","black-pepper"],"routine":[{"label":"Dose","value":"10 ml (2 tsp)"},{"label":"When","value":"Twice daily after meals"},{"label":"Tip","value":"Shake well; refrigerate after opening"}],"howToUse":["Shake well before use.","Adults: take 10 ml (2 teaspoons) twice daily after meals, using a suitable measuring cup.","Follow the dosage and duration on the approved product label, or as advised by a healthcare professional.","Store in a cool, dry place away from direct sunlight. Refrigerate after opening."],"whoFor":["Adults who want to look after their liver and digestive wellness","People with lifestyle habits that add to liver load (rich food, stress, alcohol)","Anyone looking for a plant-based daily wellness routine"],"precautions":["Not recommended for pregnant or lactating women.","Consult your physician if you are under medication.","Not a replacement for medical diagnosis, prescribed treatment or monitoring.","Keep out of reach of children."],"faqs":[["What is TranzLife Liver Booster?","A polyherbal Ayurvedic concoction (Ayurvedic Proprietary Medicine) made with 11 traditional botanicals, designed to support normal liver function, digestive wellness and overall well-being."],["What is the dosage?","Adults: 10 ml (2 teaspoons) twice daily after meals. Shake well before use. Follow the pack label or the advice of a healthcare professional."],["What is in each 10 ml?","Bhumyamalaki 500 mg, Kalmegh 400 mg, Kutki 400 mg, Punarnava 300 mg, Bhringraj 300 mg, Daruharidra 200 mg, Guduchi 200 mg, Amla 200 mg, Haritaki 200 mg, Turmeric 150 mg, black pepper 50 mg, excipients q.s."],["Does it contain sugar, colours or gluten?","No added sugar, no added colours and no artificial flavours. It is gluten-free and vegetarian. Flavour: mixed."],["Who should not take it?","It is not recommended for pregnant or lactating women. If you take medication or have a liver condition, consult your physician first."],["How should I store it?","In a cool, dry place away from direct sunlight. Refrigerate after opening."]],"brochure":"/brochures/liver-booster.pdf"}$pd$::jsonb,
       compliance = compliance || $pd${"netQuantity":"500 ml","countryOfOrigin":"India","storage":"Store in a cool, dry place away from direct sunlight. Refrigerate after opening.","certifications":["100% Ayurvedic","GMP Certified","No added sugar","No added colours"]}$pd$::jsonb, updated_at = now()
 WHERE id = $pd$liver-booster$pd$
